\fy{We} consider the following stochastic optimization problem:
\begin{equation}\label{eqn:problem}
\min_{x \in \Real^n} f(x)\fy{\ \triangleq \ }\EXP{F(x,\xi(\us{\omega}))},\tag{SO}
\end{equation}
where $F: \Real^n\times\us{\Real^d}\to\mathbb{R}$ is a \fy{real-valued} function, the random
vector $\xi$ is defined as {$\xi:\Omega
\rightarrow \Real^d$}, \us{$(\Omega,{\cal F}, \mathbb{P})$ denotes the
associated probability space\fy{,} and the expectation \us{$\EXP{F(x,\xi)}$} is
taken with respect to $\mathbb{P}$}. Problem \eqref{eqn:problem} provides a general framework that can capture a wide range of applications in operations research, machine learning, statistics and control to name a few \fys{(\vus{cf.}\cite{bottou-2010,nocedal15}). Addressing problem \eqref{eqn:problem}} has led


 \textbf{Notation:} A vector $x$ is assumed to be a column vector and
$x^T$ denotes its transpose, \an{while} $\|x\|$ {denotes} the Euclidean
vector norm, i.e., $\|x\|=\sqrt{x^Tx}$.  We write \textit{a.s.} as the
abbreviation for ``almost surely''.  \an{For a symmetric matrix $B$, 
$\lambda_{\min}(B)$ and $\lambda_{\max}(B)$ \vus{denotes the
smallest and largest eigenvalue of $B$}, respectively.} We use $\EXP{z}$ to
denote the expectation of a random variable~$z$. A function $f:X
\subset \mathbb{R}^n\rightarrow \mathbb{R}$ is said to be strongly
convex with parameter $\mu>0$, if  $f(y)\geq f(x)+\nabla
f(x)^T(y-x)+\frac{\mu}{2}\|x-y\|^2,$ for any $x,y \in X$.  A mapping
$F:X \subset \mathbb{R}^n\rightarrow \mathbb{R}$ is \vus{said to be} Lipschitz
continuous with parameter $L>0$ if for any $x, y \in X$, we have
$\|F(x)-F(y)\|\leq L\|x-y\|$. For a continuously differentiable
function $f$ with Lipschitz gradients with parameter $L>0$, we have
$f(y)\leq f(x)+\nabla f(x)^T(y-x)+\frac{L}{2}\|x-y\|^2,$ for any $x,y
\in X$. For a vector $x \in \Real^n$ and a \fys{nonempty} set $X
\subset \Real^n$, the Euclidean distance of $x$ from $X$ is denoted by
$dist(x,X)$. We denote the optimal objective value of problem
\eqref{eqn:problem} by $f^*$ and the set of the optimal solutions by
$X^*$.


In this section, we describe a general SQN scheme for solving problem~\eqref{eqn:problem} and present the main assumptions. Let $x_0\in \Real^n$ be an arbitrary initial point, and $x_k$ be generated by the following recursive rule
\begin{align}\label{eqn:LM-cyclic-reg-BFGS}\tag{IR-SQN}
x_{k+1}:=x_k -\gamma_kH_k\left(\nabla F(x_k,\xi_k)+ \mu_k(x_k-x_0)\right), \quad \hbox{for all } k \geq 0.
\end{align}

Here, $\g_k$ and $\mu_k$ are the steplength and the regularization parameter, respectively. $H_k \in \Real^{n\times n}$ is a matrix that \fy{contains} the curvature information of the objective function. The \eqref{eqn:LM-cyclic-reg-BFGS} scheme can be seen as a regularized variant of \fy{the} classical stochastic SQN \fy{method}. Here we regularize the gradient map by the term $\mu_k(x_k-x_0)$ to \fy{induce} the strong monotonicity property. In \fy{the} absence of strong convexity of $f$, unlike the classical schemes where $\mu_k$ is maintained fixed, we let $\mu_k$ be updated and \fy{decreased} to zero. Throughout, we let $\sF_k$ denote the history of the method up to time $k$, i.e., 
$\sF_k\fy{\ \triangleq \ }\{x_0,\xi_0,\xi_1,\ldots,\xi_{k-1}\}$ for $k\ge 1$, and $\sF_0\triangleq\{x_0\}$.  
\begin{assumption}\label{assum:convex}  Consider problem~\eqref{eqn:problem}. Let the following hold:
\begin{enumerate}
\item [(a)]  \an{The function $f(x)$ is convex over $\Real^n$.}  
%\an{The function $f(x)$ is convex on $\mathbb{R}^n$.} 
\item[(b)] $f(x)$ is continuously differentiable \us{with Lipschitz
	continuous gradients} over $\Real^n$ with parameter $L>0$. %Also, $\lim_{x\to \infty}f(x)< \infty$.
	\item[(c)] \ The optimal solution set of \fy{the problem} is nonempty. 
\end{enumerate}
\end{assumption}

\begin{assumption}[Random variable $\xi$]\label{assum:main}
\begin{enumerate}
\item[(a)]  \fy{Vectors $\xi_k \in \mathbb{R}^d$ are i.i.d.\ realizations of the random variable $\xi$} for any $k \geq 0$; 
\item[(b)] The stochastic gradient mapping $\nabla F(x, \xi)$ is an unbiased estimator of $\nabla f(x)$, i.e.
$\EXP{\nabla F(x,\xi)}=\nabla f(x)$ for all $x$, and has a bounded variance,
	i.e., there exists a \us{scalar} $\nu>0$ such that $\EXP{\|\nabla F(x,\xi)-\nabla f(x)\|^2} \leq \nu^2,$ for all $x \in \mathbb{R}^n$.
%Also, $\lim_{x\to \infty}f(x)< \infty$.
\end{enumerate}
\end{assumption}

\begin{assumption}[Conditions on matrix $H_k$]\label{assump:Hk}
Let the following hold for all $k\geq 0$:\\ 
(a) \  The matrix $H_k\in \Real^{n\times n}$ is $\sF_{k}$-measurable, i.e., $\EXP{H_k \mid \sF_{k}}=H_k$. \\
(b) \ Matrix $H_k$ is symmetric and positive definite and satisfies the following condition: There exist positive scalars $\lambda_{\min},\lambda$ and scalar $\alpha\leq 0$ such that $$\lambda_{\min}\mathbf{I} \preceq H_k \preceq \lambda \mu_k^\alpha\mathbf{I},\qquad  \hbox{for all }k\geq 0,$$ \fys{where $\mu_k$ is the regularization parameter in \eqref{eqn:LM-cyclic-reg-BFGS}.}
\end{assumption}

\begin{definition}[Regularized function and gradient mapping]\label{def:regularizedF}
Consider the sequence $\{\mu_k\}$ of positive \an{scalars} and the starting point of the algorithm \eqref{eqn:LM-cyclic-reg-BFGS}, i.e., $x_0$.
% for $k \geq 0$. 
The regularized function $f_k$ and its gradient are defined as follows \fys{for all $k\geq 0$}:
\begin{align*}
f_k(x)\triangleq  f(x)+\frac{\mu_k}{2}{\|x-x_0\|^2},\quad \nabla f_k(x)\triangleq\nabla f(x)+\mu_k(x-x_0).
\end{align*}
\end{definition}

In a similar way, we denote the regularized stochastic function $F(x,\xi)$ and its gradient with $F_k$ and $\nabla F_k$ for any $\xi$, respectively. 


Throughout, we denote the stochastic error of the gradient estimator by 
\begin{align}
\label{def:wk}w_k\triangleq \nabla F(x_k,\xi_k)-\nabla f(x_k), \an{\quad\hbox{for all }k\ge0.} 
\end{align}

Note that under Assumption \ref{assum:main}, from the definition of $w_k$ in \eqref{def:wk}, we obtain $\EXP{w_k\mid \sF_k}=0$ and $\EXP{\|w_k\|^2\mid \sF_k}\fy{\leq}  \nu^2$. \fy{The following result plays a key role in the convergence and rate analysis of the proposed schemes.}


\begin{assumption}[\fy{Conditions} on sequences for a.s. convergence]\label{assum:sequences}
Let the sequences $\{\gamma_k\}$ and $\{\mu_k\}$ be positive and satisfy the following conditions:
\begin{flalign*}
\begin{array}{lll}
\vspace{.2in}(a)\  \fy{\lim_{k \to \infty }\g_k\mu_k^{2\alpha-1} =0;}& &(b)\ \{\mu_k\}\hbox{ is non-increasing and }\mu_k \to 0;\\
\vspace{.2in}(c)\  \lambda_{\min}\g_k\mu_k \leq 1\hbox{ for }k \geq 0; && (d)\ \sum_{k=0}^\infty \g_k\mu_k =\infty;\\
(e)\ \sum_{k=0}^\infty \mu_k^2\g_k <\infty;&&(f)\  \sum_{k=0}^\infty \g_k^2\mu_k^{2\alpha} <\infty\fy{.}
\end{array}
\end{flalign*}
\end{assumption}

\begin{assumption}[\fy{Conditions} on sequences for convergence in mean]\label{assum:sequences-ms-convergence}
Let the sequences $\{\gamma_k\}$ and $\{\mu_k\}$ be positive and satisfy the following conditions:
\begin{itemize}
\item [(a)] $\lim_{k \to \infty }\g_k\mu_k^{2\alpha-1} =0$;
\item [(b)] $\{\mu_k\}\hbox{ is non-increasing and }\mu_k \to 0$;
\item [(c)] $\lambda_{\min}\g_k\mu_{k} \leq 1$ for $k \geq 0$;
%\item [(d)] $\g_k\mu_k^{2\alpha}\leq \frac{\lambda{\min}}{\lambda^2(L+\mu_0)}$ for all $k\geq 0$;
\item [(d)] There exist $K_0$ and $0<\beta<1$ such that \begin{align*}\g_{k-1}\mu_{k-1}^{2\alpha-1}\leq \g_{k}\mu_{k}^{2\alpha-1}(1+\beta \lambda_{\min}\g_{k}\mu_{k}),\quad \hbox{for all }k \geq K_0;\end{align*}
\item [(e)] There exists a scalar $\rho>0$ such that $ \mu_k^{2-2\alpha} \leq \rho\g_k$ for all $k \geq 0$\fy{.}
\end{itemize}
\end{assumption}

\begin{align}\label{eqn:mu-k}
  \begin{cases}
   \mu_{k}\fy{:=}\mu_{k-1},      &   \text{if } k \text{ is odd},\\
    \mu_{k}<\mu_{k-1},  &    \text{otherwise}\fy{.}
  \end{cases}
\end{align}

Note that we allow for updating the stepsize sequence at each iteration.


\begin{align}\label{equ:siyi-LBFGS}&s_{\lceil k/2\rceil}:= x_{k}-x_{k-1},\cr 
&y_{\lceil k/2\rceil}:=  \nabla F(x_{k},\xi_{k-1}) -\nabla F(x_{k-1},\xi_{k-1})  +  \fys{\tau}\mu_k^\delta s_{\lceil k/2\rceil},\end{align}

\begin{align}\label{eqn:H-k}H_{k}\fy{\triangleq}
  \begin{cases}
    H_{k,m},  &    \text{if } k \text{ is odd}, \\
    H_{k-1},  &   \text{otherwise},
  \end{cases}
\end{align}

where $m<n$ (in the large scale settings, \fys{$m\ll n$}) is \fy{the memory parameter and represents} the number of pairs \fy{$(s_i,y_i)$} to be \fys{stored} to estimate $H_k$. Matrix $H_{k,m}$, for any \fy{odd $k\geq 2m-1$}, is updated using the following recursive formula:
\begin{align}\label{eqn:H-k-m}
H_{k,j}:=\left(\mathbf{I}-\frac{y_is_i^T}{{y_i^Ts_i}}\right)^TH_{k,j-1}\left(\mathbf{I}-\frac{y_is_i^T}{y_i^Ts_i}\right)+\frac{s_is_i^T}{y_i^Ts_i}, \quad 1 \leq j\leq m,
\end{align}

where \fy{$i\triangleq \lceil k/2\rceil-(m-j)$ and we set $H_{k,0}:=\frac{s_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}{y_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}\mathbf{I}$}. Here, at odd iterations, matrix $H_k$ is obtained recursively from $H_{k,0},H_{k,1},\ldots, H_{k,m-1}$. Note that \fy{computation of} $H_k$ at an odd $k$ \fy{needs} $m$ pairs \fy{of} \fy{$(s_i,y_i)$}. More precisely, $H_k$ uses the following curvature information: $\left\{(s_i,y_i)\mid i=\lceil k/2\rceil-m+1, \lceil k/2\rceil-m+2,\ldots,\lceil k/2\rceil\right\}.$ 
For convenience, in the first \fys{$2m-2$} iterations, we \fy{let $H_k$ be the identity matrix}. \fy{This allows for collecting the first set of $m$ pairs $(s_i,y_i)$, where $i=1,2,\ldots,m$, that is used at iteration $k:=2m-1$ to obtain $H_{2m-1}$}. \fys{The main differences between update rule \eqref{eqn:H-k-m} and that of the standard SQN schemes~\cite{Mokhtari15,nocedal15} are as follows:} (i) The first distinction is with respect to the definition of $y_i$ in \eqref{equ:siyi-LBFGS}. Here the term $\fy{\mu_k^\delta s_{\lceil k/2\rceil}}$ \vus{compensates} for the lack of strong monotonicity of the gradient mapping and \vus{aids in} establishing the \fy{curvature condition}. (ii) Second, instead of obtaining the pair $(s_i,y_i)$ at every iteration, we \fy{evaluate these terms only at} odd iterations to allow for updating the regularization parameter satisfying \eqref{eqn:mu-k}. %\vus{\bf Farzad -- doesnt the paper by Mokhtari also do odd updates...clarify} 


\begin{assumption}\label{assum:convex2}  
\begin{enumerate}
\item [(a)]  \an{The function $F(x,\xi)$ is convex over $\Real^n$ for any $\xi \in \Omega$.}  
%\an{The function $f(x)$ is convex on $\mathbb{R}^n$.} 
\item[(b)] For any $\xi \in \Omega$, $F(\cdot,\xi)$ is continuously differentiable \us{with Lipschitz
	continuous gradients} over $\Real^n$ with parameter $L_\xi>0$. Moreover, $L:=\sup_{\xi \in \Omega}L_\xi < \infty$. %Also, $\lim_{x\to \infty}f(x)< \infty$.
	\item[(c)] \ The optimal solution set $X^*$ of problem \eqref{eqn:problem} is nonempty. 
\end{enumerate}
\end{assumption}

\begin{algorithm}
  \caption{Iteratively Regularized Stochastic Limited-memory BFGS}
\label{algorithm:IR-S-BFGS}
%\begin{boxedminipage}{165mm}
    \begin{algorithmic}[1]
    \State\textbf{Input:} LBFGS memory parameter $m\geq 1$, Lipschitzian parameter $L>0$, random initial point $x_0 \in \Real^n$, initial stepsize $\g_0>0$, and initial regularization parameter $\mu_0>0$ such that $\g_0\mu_0 \leq  (m+n) L$, \fys{scalars $0<\epsilon < \frac{1}{3}$, $\delta \in \left(0,\frac{1.5\epsilon}{n+m}\right)$, and $\tau>0$}; 
    \State Set $a:=\frac{2}{3}-\epsilon+\frac{2\delta(n+m)}{3}$, $b:=\frac{1}{3}$;
    \For {$k=0,1,\ldots,$}
    		\State Compute $\g_k :=\frac{\g_0}{(k+1)^a}$ and $\mu_k:=\frac{\mu_02^b}{\left(k+1+\text{mod}(k+1,2)\right)^b}$;
        \State  {Evaluate the stochastic gradient $\nabla F(x_k,\xi_k)$;}
     \If {mod$(k,2)=1$}
    \State  Compute index $i:=\lceil k/2\rceil$;
     \State   Compute vector $s_i:=x_k-x_{k-1}$; 
     \State   Compute vector  $y_i:= \nabla F(x_k,\xi_{k-1})-\nabla F(x_{k-1},\xi_{k-1})+\fys{\tau}\mu_k^\delta s_i$;
      \If {$k> 2m$}
      \State Discard the vector pair $\{s_{i-m},y_{i-m}\}$ from storage;
      \EndIf
   \EndIf
 \If {$k < 2m-1$}
   \State Update solution iterate $x_{k+1}:=x_k-\g_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right)$;
     \Else
     \State Initialize Hessian inverse $H_{k,0}:=\frac{s_i^Ty_i}{y_i^Ty_i}\mathbf{I}$;\hspace{.4in} \tikzmark{right}\tikzmark{top}
     \State Initialize $q:=\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)$;
     \For {$t=i:i-m+1$}
     \State Compute scalar $\alpha_{i-t+1}:=\frac{s_t^Tq}{s_t^Ty_t}$;
     \State Update vector $q:=q-\alpha_{i-t+1}y_t$;
     \EndFor
     \State Initialize vector $r:=H_{k,0}q$;
     \For {$t=i-m+1:i$}
     %\State Compute scalar $\beta:=\frac{y_t^Tr}{s_t^Ty_t}$;
     \State  Update vector $r:=r+\left(\alpha_{i-t+1}-\frac{y_t^Tr}{s_t^Ty_t}\right)s_t$;
     \EndFor\tikzmark{bottom}
%\State Given $\mathcal{M}=\{(s_t,y_t)\}_{t=i-m+1}^i$, call Alg. \ref{algorithm:Hk-update} to compute the following vector\[G_k \triangleq H_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right);\]
             \State Update solution iterate $x_{k+1}:=x_k-\g_kr$;\Comment{\footnotesize{LBFGS update}} 

\EndIf

    \EndFor
   \end{algorithmic}
   \AddNote{top}{bottom}{right}{\footnotesize{LBFGS two-loop recursion}}
%\end{boxedminipage}
% \vskip17.5pt
\end{algorithm}

