\begin{proof} \fys{Throughout, we let $\lambda_{k,\min}$, $\lambda_{k,\max}$, and $B_k$ denote the minimum eigenvalue, maximum eigenvalue, and inverse of matrix $H_k$ in \eqref{eqn:H-k-m}, respectively.}
It can be seen, by induction on $k$, that \fy{$H_k$ is symmetric and $\sF_k$ measurable.} We use induction on odd values of \fys{$k\geq 2m-1$ to show that parts (a), (b), and (c) hold.} Suppose \fy{$k\geq 2m-1$} is odd and for any \fys{odd} $t<k$, we have \fy{$s_{\lceil t/2\rceil}^T{y_{\lceil t/2\rceil}} >0$, $H_{t}{y}_{\lceil t/2\rceil}=s_{\lceil t/2\rceil}$}, and \eqref{proof:H_kbounds} for $t$. We show that these statements also hold for $k$ \fys{as well}. First, we \fys{show} that the \fy{curvature condition} holds. We can write 
\begin{align*}
\fys{s_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}&=(x_{k}-x_{k-1})^T(\nabla F(x_k,\xi_{k-1})- \nabla F(x_{k-1},\xi_{k-1})+\fys{\tau}\mu_k^\delta(x_k-x_{k-1}))\\
&=(x_{k}-x_{k-1})^T(\nabla F(x_k,\xi_{k-1})- \nabla F(x_{k-1},\xi_{k-1}))+\fys{\tau}\mu_k^\delta\|x_k-x_{k-1}\|^2\\
&\geq \fys{\tau}\mu_k^\delta\|x_k-x_{k-1}\|^2,
\end{align*}
where the inequality follows from the monotonicity of the gradient map $\nabla F(\cdot,\xi)$. \fys{Next, we show that $\|x_k-x_{k-1}\|^2 >0$.} From the induction hypothesis \fys{and that $k-2$ is odd}, $H_{k-2}$ is positive definite.
\fys{Moreover, from the update rule \eqref{eqn:H-k} and that $k-2$ is odd, we have $H_{k-1}=H_{k-2}$.}  
%Also, since $B_{k-2}$ is symmetric, the update rule \eqref{eqn:B-k} implies that $B_{k-1}$ is symmetric.
Therefore, $H_{k-1}$ is \fys{also} positive definite. \fy{Without loss of generality, we assume $\nabla F(x_{k-1},\xi_{k-1})+\mu_{k-1}(x_{k-1}-x_0)\neq 0$}\footnote{If $\nabla F(x_{k},\xi_k)+\mu_{k}(x_k-x_0)=0$\fys{,} then we can draw a new sample of $\xi_k$ to satisfy the relation.}.
Since $H_{k-1}$ is positive definite, 
we have $$H_{k-1}\left(\nabla F(x_{k-1},\xi_{k-1})+\mu_{k-1}\fy{(x_{k-1}-x_0)}\right) \neq 0,$$ implying that 
$x_{k} \neq x_{k-1}$. Hence
$\fy{s_{\lceil k/2\rceil}^T{y_{\lceil k/2\rceil}} }\geq  \fys{\tau}\mu_k^\delta\|x_k-x_{k-1}\|^2 >0,$
where \us{the second inequality is a consequence of} $\fys{\tau},\mu_k>0$.
Thus, the \fy{curvature condition} holds.
Next, we show that \eqref{proof:H_kbounds} holds for $k$. It is well-known that using the Sherman-Morrison-Woodbury formula, $B_k$ is equal to $B_{k,m}$ given by 
\begin{align}\label{equ:B_kLimited}
B_{k,j}=B_{k,j-1}-\frac{B_{k,j-1}s_is_i^TB_{k,j-1}}{s_i^TB_{k,j-1}s_i}+\frac{y_iy_i^T}{y_i^Ts_i}, \quad i:=\fy{{\lceil k/2\rceil}-(m-j)}, \quad 1 \leq j \leq m,
\end{align}
where $s_i$ and $y_i$ are defined by \eqref{equ:siyi-LBFGS} and \fy{$B_{k,0}=\frac{y_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}{s_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}\mathbf{I}$}. \fys{Note that with $j$ varying between $1$ to $m$, the index $i$ takes values in $\left\{\lceil k/2\rceil-m+1,\lceil k/2\rceil-m+2,\ldots,\lceil k/2\rceil\right\}$.} First, we show that for any $i$ \fys{in this range}, \begin{align}\label{equ:boundsForB0}
\fys{\tau}\mu_k^\delta \leq \frac{\|y_i\|^2}{y_i^Ts_i} \leq L+\fys{\tau}\mu_k^\delta,
\end{align}
 where $L$ is the Lipschitzian parameter of the gradient mapping $\nabla F$ \fys{given by Assumption \ref{assum:convex2}(b)}. Let us \fys{define the function $h(x)\triangleq F(x,\xi_{i-1})+\tau\frac{\mu_k^\delta}{2}\|x-x_0\|^2$} for fixed $i$ and $k$. Note that this function is strongly convex and has a gradient mapping of the form $\nabla F+\fys{\tau}\mu_k^\delta(\mathbf{I}-x_0)$ that  is Lipschitz with parameter $L+\fys{\tau}\mu_k^\delta$. For a convex function $h$ with Lipschitz gradient with parameter $L+\fys{\tau}\mu_k^\delta$, the following inequality, referred to as co-coercivity  property, holds for any $x_1,x_2 \in \Real^n$ \fys{(see}\cite{Polyak87}, Pg. 24 , Lemma 2):
 \[\|\nabla h(x_2)-\nabla h(x_1)\|^2 \leq \left(L+\fys{\tau}\mu_k^\delta\right)(x_2-x_1)^T(\nabla h(x_2)-\nabla h(x_1)).\]
Substituting $x_2$ by $x_i$, $x_1$ by $x_{i-1}$, and recalling \eqref{equ:siyi-LBFGS}, the preceding inequality yields
\begin{align}\label{ineq:boundsForB0-1}\|y_i\|^2 \leq \left(L+\fys{\tau}\mu_k^\delta\right)s_i^Ty_i.\end{align}
Note that function $h$ is strongly convex \fy{with} parameter $\fys{\tau}\mu_k^\delta$. Applying the Cauchy-Schwarz inequality, we can write
\[\frac{\|y_i\|^2}{s_i^Ty_i} \geq \frac{\|y_i\|^2}{\|s_i\|\|y_i\|} =\frac{\|y_i\|}{\|s_i\|}\geq  \frac{\|y_i\|\|s_i\|}{\|s_i\|^2} \geq \frac{y_i^Ts_i}{\|s_i\|^2}\geq \fys{\tau}\mu_k^\delta.\]
Combining this relation with \eqref{ineq:boundsForB0-1}, we obtain \eqref{equ:boundsForB0}. Next, we show that the maximum eigenvalue of $B_k$ is bounded. Let $Trace(\cdot)$ denote the trace of a matrix. Taking trace from both sides of \eqref{equ:B_kLimited} and summing up over index $j$, we obtain \fy{for $i:={\lceil k/2\rceil}-(m-j)$,}
\begin{align}\label{ineq:trace}
Trace(B_{k,m})&=Trace(B_{k,0})-\sum_{j=1}^m Trace\left(\frac{B_{k,j-1}s_is_i^TB_{k,j-1}}{s_i^TB_{k,j-1}s_i}\right)+\sum_{j=1}^m Trace\left(\frac{y_iy_i^T}{y_i^Ts_i}\right)\cr
& =Trace\fy{\left(\frac{\|y_{\lceil k/2\rceil}\|^2}{s_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}\mathbf{I}\right)} - \sum_{j=1}^m \frac{\|B_{k,j-1}s_i\|^2}{s_i^TB_{k,j-1}s_i} + \sum_{j=1}^m \frac{\|y_i\|^2}{y_i^Ts_i}\cr 
&\leq n \fy{\frac{\|y_{\lceil k/2\rceil}\|^2}{s_{\lceil k/2\rceil}^Ty_{\lceil k/2\rceil}}} +\sum_{j=1}^m \left(L+\fys{\tau}\mu_k^\delta\right) \fy{\leq} (m+n)\left(L+\fys{\tau}\mu_k^\delta\right),
\end{align}
where the third relation is obtained by positive-definiteness of $B_k$ (this can be seen by induction on \fys{$j$}, and using \eqref{equ:B_kLimited} and $B_{k,0}\succ 0$). Since $B_k=B_{k,m}$, the maximum eigenvalue of the matrix $B_k$ is bounded \fys{by $(m+n)\left(L+\tau\mu_k^\delta\right)$}. As a result, 
\begin{align}\label{proof:lowerbound}
\lambda_{k,\min}\geq \frac{1}{(m+n)\left(L+\fys{\tau}\mu_k^\delta\right)}.\end{align}
 In the next part of the proof, we establish the bound for $\lambda_{k,\max}$. The following relation can be shown (e.g., see Lemma 3 in \cite{Mokhtari15})
\begin{align*}
det(B_{k,m})=det(B_{k,0})\prod_{j=1}^m\frac{s_i^Ty_i}{s_i^TB_{k,j-1}s_i}\fy{, \quad \hbox{for }i:={\lceil k/2\rceil}-(m-j)}.
\end{align*}
