\fy{From the assumption that $\frac{a}{b}>1+2\delta(m+n)$, we obtain$-a+(1-2\alpha) b<0$}. Thus, the preceding term goes to zero verifying Assumption \ref{assum:sequences}(a).\\
(b) Let $k$ be an even number. Thus, $\kappa=2$. From \eqref{equ:seq} we have $\mu_{k}=\mu_{k+1}=\frac{\mu_02^b}{\left(k+2\right)^b}$. Now, let $k$ be an odd number. Again, according to \eqref{equ:seq} can write 
\[\mu_{k+1}=\frac{\mu_02^b}{\left((k+1)+2\right)^b }<\frac{\mu_02^b}{\left(k+1\right)^b}= \frac{\mu_02^b}{\left(k+\kappa\right)^b}=\mu_k.\]
Therefore, $\mu_k$ given by \eqref{equ:seq} satisfies \eqref{eqn:mu-k}. Also, from \eqref{equ:seq} we have $\mu_k \to 0$. Thus, Assumption \ref{assum:sequences}(b) holds.\\
(c) The given rules \eqref{equ:seq} imply that $\g_k$ and $\mu_k$ are both non-increasing sequences. Therefore, we have $\g_k\mu_{k} \leq \g_0\mu_{0}$ for any $k\geq 0$. So, to show that Assumption \ref{assum:sequences}(c) holds, it is enough to show that $\lambda_{\min}\g_0\mu_{0} \leq 1$ where $\lambda_{\min}$ is given by \eqref{equ:valuesForAssumH_k}. Since we assumed that $\g_0\mu_0 \leq L(m+n)$, for any $\delta \in (0,1]$, we have $\g_0\mu_0 \leq (m+n)(L+\mu_0^\delta)$, implying that $\lambda_{\min}\g_0\mu_{0} \leq 1$ and that Assumption \ref{assum:sequences}(c) holds.\\
(d) From \eqref{equ:seq}, we can write $$\sum_{k=0}^\infty \g_k\mu_k =\g_0\mu_02^b\sum_{k=0}^\infty (k+1)^{-a}(k+\kappa)^{-b} \geq \g_0\mu_02^b\sum_{k=0}^\infty (k+2)^{-(a+b)}= \infty,$$
where the last relation is due to $a+b\leq 1$. Therefore, Assumption \ref{assum:sequences}(d) holds.\\
(e) Using \eqref{equ:seq}, it follows
\fy{\begin{align*}&\sum_{k=0}^\infty \g_k\mu_k^2 =  \g_0\mu_0^24^b\sum_{k=0}^\infty (k+1)^{-a}(k+\kappa)^{-2b}\leq   \g_0\mu_0^24^b\sum_{k=0}^\infty (k+1)^{-(a+2b)}<\infty,\end{align*}}
where the last inequality is due to \an{$a+2b>1$}. Therefore, Assumption \ref{assum:sequences}(e) holds.\\
(f) From \eqref{equ:seq}, we have
\begin{align*}&\sum_{k=0}^\infty \g_k^2\mu_k^{2\alpha} %=  \g_0^2(\mu_02^b)^{2\alpha}\sum_{k=0}^\infty \frac{(k+\kappa)^{-2\alpha b}}{(k+1)^{2a}} 
\leq  \g_0^2(\mu_02^b)^{2\alpha}\left(\sum_{k=0}^1 \frac{(k+\kappa)^{-2\alpha b}}{(k+1)^{2a}}+\sum_{k=2}^\infty \frac{(2k)^{-2\alpha b}}{k^{2a}}\right)<\infty 
%&=  \frac{\g_0^2}{\mu_0^24^c}\left(\sum_{k=0}^1 \frac{(k+\kappa)^{2c}}{(k+1)^{2a}}+4^c\sum_{k=2}^\infty k^{2(c-a)}\right)<\infty,
\end{align*}
where in the first inequality, we use $\alpha <0$ and in the last inequality, we note that 
$a+\alpha b=a-\delta\left(m+n\right)b>0.5$. Therefore, Assumption \ref{assum:sequences}(f) is verified.
\end{proof}

\begin{proof}
\fy{Throughout, we let $\alpha$ denote $-\delta(m+n)$.} \fys{Assumption \ref{assum:sequences-ms-convergence}(a, b, c) and \eqref{eqn:mu-k} have been already shown in parts (a, b, c) of the proof of Lemma \ref{lemma:a.s.sequences}.}\\
\noindent
%(d) From part (a), since the term $\g_k\mu_k^{2\alpha-1}$ goes to zero, there exist $K_2>0$ such that $\g_k\mu_k^{2\alpha-1}\leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_0)}$ for all $k \geq K_2$, implying that Assumption \ref{assum:sequences-ms-convergence}(d) holds for a large enough $k$. \\
%\noindent
(d) It suffices to show there exists \fy{$K_0$} such that for any $k \geq K_0$ and $0<\beta<1$, 
\begin{align}\label{ineq:partd}\frac{\g_{k-1}}{\g_k}\frac{\mu_{k}^{1-2\alpha}}{\mu_{k-1}^{1-2\alpha}}-1\leq \beta \lambda_{\min}\g_k\mu_k.\end{align}
From \eqref{equ:seq} \fy{and the definition of $\alpha$}, we obtain 
\begin{align*}&\frac{\g_{k-1}}{\g_k}\frac{\mu_{k}^{1-2\alpha}}{\mu_{k-1}^{1-2\alpha}}-1
\leq \frac{\g_{k-1}}{\g_k}-1=\left(1+\frac{1}{k}\right)^a-1= 1+\frac{a}{k}+\fy{{o}\left(\frac{1}{k}\right)}-1=\mathcal{O}\left(\frac{1}{k}\right),
\end{align*}
where the first inequality is implied due to $\{\mu_k\}$ is non-increasing, and in the second equation, we used the Taylor's expansion of $\left(1+\frac{1}{k}\right)^a$. Therefore, since the right-hand side of \eqref{ineq:partd} is of the order $\frac{1}{k^{a+b}}$ and that $a+b<1$, the preceding inequality shows that such $K_0$ exists for which Assumption \ref{assum:sequences-ms-convergence}(d) holds for all $0<\beta<1$.\\
\noindent
(e) From \eqref{equ:seq}, we have 
\begin{align*} \frac{\mu_k^{2-2\alpha}}{\g_k}& =\fy{\g_0}^{-1}\left(\mu_02^b\right)^{2-2\alpha}(k+\kappa)^{-b(2-2\alpha)}(k+1)^{a} \leq\frac{\fy{\gamma_0}^{-1}\left(\mu_02^b\right)^{2-2\alpha}}{(k+1)^{-a+(2-2\alpha)b}}\\&\leq \fy{\gamma_0}^{-1}\left(\mu_02^b\right)^{2-2\alpha}=\rho, \end{align*}
where the first inequality is due to \fy{$\alpha <0$, and the second inequality follows by the assumption $a\leq 2b(1+\delta(m+n))$}. Therefore, Assumption \ref{assum:sequences-ms-convergence}(e) is satisfied.
\end{proof}

