\begin{property}[{Properties of a regularized function}]\label{proper:propsfk} We have:
\begin{itemize}
\item [(a)] $f_k$ is strongly convex with a parameter $\mu_k$.
\item [(b)] $f_k$ has Lipschitzian gradients with parameter $L+\mu_k$.
 \item [(c)] $f_k$ has a unique minimizer over $\Real^n$, denoted by $x^*_k$. Moreover, for any $x \in \Real^n$, 
 \[2\mu_k (f_k(x)-f_k(x^*_k)) \leq \|\nabla f_k(x)\|^2\leq 2(L+\mu_k) (f_k(x)-f_k(x^*_k)).\]
\end{itemize}
\end{property}

\begin{lemma}[A recursive error bound]\label{lemma:main-ineq}
Consider the \eqref{eqn:LM-cyclic-reg-BFGS} method and suppose Assumptions \ref{assum:convex}, \ref{assum:main}, and \ref{assump:Hk} hold. Also, assume $\mu_k$ is a non-increasing sequence and let \begin{align}\label{mainLemmaCond}\g_k\mu_k^{2\alpha} \leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_0)},\quad \hbox{for all }k\geq 0.
\end{align}Then, the following inequality holds \fy{for all $k\geq 0$}:
\begin{align}\label{ineq:cond-recursive-F-k}
\EXP{f_{k+1}(x_{k+1})\mid\sF_k}-f^* &\leq (1-\lambda_{\min}\mu_k\g_k)(f_k(x_k)-f^*)+\frac{\lambda_{\min}\mbox{dist}^2(x_0,X^*)}{2}\mu_k^2\g_k\notag \\ &+\frac{ (L+\mu_k)\lambda^2\nu^2}{2}\mu^{2\alpha}_k\g_k^2.
\end{align}
\end{lemma}

\begin{proof}
The Lipschitzian property of $\nabla f_k$ and  
the update rule \eqref{eqn:LM-cyclic-reg-BFGS} imply that 
\begin{align*}
f_k(x_{k+1}) &\leq f_k(x_k)+\nabla f_k(x_k)^T(x_{k+1}-x_k)+\frac{ (L+\mu_k)}{2}\|x_{k+1}-x_k\|^2 \cr
&= f_k(x_k)-\g_k\nabla f_k(x_k)^TH_k\left(\nabla F(x_k,\xi_k) +\mu_k(x_k-x_0)\right)\\&+ \frac{ (L+\mu_k)}{2}\g_k^2\|H_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right)\|^2.\end{align*}
\fy{Invoking the definition of the stochastic error $w_k$ in} \eqref{def:wk} \fy{and} Definition~\ref{def:regularizedF}, we obtain
\begin{align}\label{ineq:term1-2}
f_k(x_{k+1}) &\leq f_k(x_k)-\g_k\nabla f_k(x_k)^TH_k(\nabla f(x_k)+w_k +\mu_k(x_k-x_0))\notag\\&+ \frac{ (L+\mu_k)}{2}\g_k^2\|H_k(\nabla f(x_k)+w_k+\mu_k(x_k-x_0))\|^2\\ 
\notag = f_k(x_k)&-\g_k\underbrace{\nabla f_k(x_k)^TH_k(\nabla f_k(x_k)+w_k)}_{\tiny\hbox{Term } 1}+ \frac{ (L+\mu_k)}{2}\g_k^2\underbrace{\|H_k(\nabla f_k(x_k)+w_k)\|^2}_{\tiny\hbox{ Term } 2},\end{align}
where in the last \fy{equation,} we used the definition of $f_k$. Next, we estimate the conditional expectation of Term 1 and 2. From Assumption \ref{assump:Hk}, we have 
\begin{align*}
\hbox{Term }1 &= \nabla f_k(x_k)^TH_k\nabla f_k(x_k)+\nabla f_k(x_k)^TH_kw_k \\&\geq \lambda_{\min}\|\nabla f_k(x_k)\|^2+\nabla f_k(x_k)^TH_kw_k.
\end{align*}
Taking expectations conditioned on $\sF_k$, from the preceding inequality, we obtain
\begin{align}\label{equ:Term1}
\EXP{\hbox{Term } 1\mid\sF_k} &\geq \lambda_{\min}\|\nabla f_k(x_k)\|^2+\EXP{\nabla f_k(x_k)^TH_kw_k\mid\sF_k}\\ \notag&=\lambda_{\min}\|\nabla f_k(x_k)\|^2+\nabla f_k(x_k)^TH_k\EXP{w_k\mid\sF_k} =\lambda_{\min}\|\nabla f_k(x_k)\|^2,\end{align}
where we recall that $\EXP{w_k\mid\sF_k}=0$ and $\EXP{H_k\mid\sF_k}=H_k$. Similarly, in Term 2, invoking Assumption \ref{assump:Hk}(b), we may write
\begin{align*}
\hbox{Term } 2&= (\nabla f_k(x_k)+w_k)^TH_k^2(\nabla f_k(x_k)+w_k)\leq (\lambda\mu^{\alpha}_k)^2\|\nabla f_k(x_k)+w_k\|^2 \\ &=\lambda^2\mu^{2\alpha}_k\left(\|\nabla f_k(x_k)\|^2+\|w_k\|^2+2\nabla f_k(x_k)^Tw_k\right).\end{align*}
Taking conditional expectations from the preceding inequality, and using Assumption \ref{assum:main}, we obtain
\begin{align}\label{equ:Term2}
\EXP{\hbox{Term } 2\mid\sF_k}&\leq\lambda^2\mu^{2\alpha}_k\left(\|\nabla f_k(x_k)\|^2+\EXP{\|w_k\|^2\mid\sF_k}+2\nabla f_k(x_k)^T\EXP{w_k\mid\sF_k}\right)\notag\\ & \leq \lambda^2\mu^{2\alpha}_k\left(\|\nabla f_k(x_k)\|^2+\nu^2\right).\end{align}
Next, taking conditional expectations in \eqref{ineq:term1-2}, and using \eqref{equ:Term1} and \eqref{equ:Term2}, we obtain
\begin{align*}%\label{ineq:lemma2rel7}
&\EXP{f_k(x_{k+1})\mid\sF_k} \leq f_k(x_k)-\g_k\lambda_{\min}\|\nabla f_k(x_k)\|^2\notag \\
&+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\left(\|\nabla f_k(x_k)\|^2+\nu^2\right)\notag \\
&\leq f_k(x_k)-\frac{\g_k\lambda_{\min}}{2}\|\nabla f_k(x_k)\|^2\left(2-\frac{\lambda^2\mu_k^{2\alpha}\g_k(L+\mu_k)}{\lambda_{\min}}\right)+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align*}
From the assumption that $\g_k$ and $\mu_k$ satisfy $\g_k\mu^{2\alpha}_k \leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_0)}$ for any $k \geq 0$ and that $\mu_k$ is non-increasing, we have $\g_k\mu^{2\alpha}_k \leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_k)}$. As a consequence, we get $2-\frac{\lambda^2\mu_k^{2\alpha}\g_k(L+\mu_k)}{\lambda_{\min}}\geq 1$.  Therefore, from \fy{the} preceding inequality, we obtain
\begin{align*}
\EXP{f_k(x_{k+1}) \mid\sF_k}&\leq f_k(x_k)-\frac{\g_k\lambda_{\min}}{2}\|\nabla f_k(x_k)\|^2+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align*}
Employing Property \ref{proper:propsfk}(c), we have
\begin{align*}
\EXP{f_k(x_{k+1})\mid\sF_k} &\leq f_k(x_k)-\lambda_{\min}\mu_k\g_k(f_k(x_k)-f_k(x^*_k))+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align*}
Note that, since $\mu_k$ is a non-increasing sequence, Definition \ref{def:regularizedF} implies that \[\EXP{f_{k+1}(x_{k+1})\mid \sF_k} \leq\EXP{f_{k}(x_{k+1})\mid \sF_k}.\] Therefore, we obtain 
\begin{align}\label{ineq:lemmaLastIneq}
\EXP{f_{k+1}(x_{k+1})\mid\sF_k} &\leq f_k(x_k)-\lambda_{\min}\mu_k\g_k(\underbrace{f_k(x_k)-f_k(x^*_k)}_{\tiny{\hbox{Term } 3}})+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align}
Next, we derive a lower bound for Term 3. Since $x_k^*$ is the unique minimizer of $f_k$, we have $f_k(x_k^*) \leq f_k(x^*)$. Therefore, invoking Definition \ref{def:regularizedF}, for an arbitrary optimal solution $x^* \in X^*$, we have 
\[f_k(x_k)-f_k(x^*_k)\geq f_k(x_k)-f_k(x^*)=f_k(x_k)-f^*-\frac{\mu_k}{2}\|x^*-x_0\|^2.\]
From the preceding relation and \eqref{ineq:lemmaLastIneq}, we have
\begin{align*}
\EXP{f_{k+1}(x_{k+1})\mid\sF_k} &\leq f_k(x_k)-\lambda_{\min}\mu_k\g_k(f_k(x_k)-f^*)+\frac{\lambda_{\min}\|x^*-x_0\|^2}{2}\mu_k^2\g_k\\
&+\frac{(L+\mu_k)\lambda^2\nu^2}{2}\mu^{2\alpha}_k\g_k^2.
\end{align*}
Since $x^*$ is an arbitrary optimal solution, taking minimum from the right-hand side of the preceding inequality over $X^*$, we can replace $\|x^*-x_0\|$ by $\mbox{dist}(x_0,X^*)$. Then, subtracting $f^*$ from both sides of the resulting relation yields the desired inequality.
\end{proof}

\begin{proposition}[Convergence in mean]\label{prop:mean}
Consider the \eqref{eqn:LM-cyclic-reg-BFGS} scheme. 
Suppose Assumptions~\ref{assum:convex},
\ref{assum:main}, \ref{assump:Hk}, and \ref{assum:sequences-ms-convergence} hold. 
Then, there exists $K\geq 1$ such that:\begin{align}\label{ineq:bound}
 \EXP{f(x_{k+1})}-f^*\leq \theta\g_k\mu_k^{2\alpha-1}, \quad \hbox{for all } k \geq K,
 \end{align}
  where $f^*$ is the optimal value of problem \fy{and}
\begin{align}\label{def:theta}\theta := \max \bigg\{\frac{\EXP{f_{K+1}(x_{K+1})}-f^*}{\g_K\mu_K^{2\alpha-1}},\frac{\rho\lambda_{\min}\mbox{dist}^2(x_0,X^*)+ (L+\mu_0)\lambda^2\nu^2}{2\fy{\lambda_{\min}}(1-\beta)}\bigg\}.\end{align}
 Moreover, $\lim_{k\to \infty}\EXP{f(x_{k})}=f^*.$
\end{proposition}

\begin{proof}
Note that Assumption \ref{assum:sequences-ms-convergence}(a,b) imply that \eqref{ineq:cond-recursive-F-k} holds for a large enough $k$, say after $\hat K$. Then, since the conditions of Lemma \ref{lemma:main-ineq} are met \fy{(with an index shift)}, taking expectations on both sides of \eqref{ineq:cond-recursive-F-k}, we obtain for any $k\geq \hat K$:
\begin{align*}
\EXP{f_{k+1}(x_{k+1})-f^*} &\leq (1-\lambda_{\min}\mu_k\g_k)\EXP{f_k(x_k)-f^*}+\frac{\lambda_{\min}\mbox{dist}^2(x_0,X^*)}{2}\mu_k^2\g_k\\ &+\frac{ (L+\mu_0)\lambda^2\nu^2}{2}\mu^{2\alpha}_k\g_k^2.
\end{align*}
%{\bf Comment: the relation in (9) has different coefficients than originally - edits needed from here onward}
 Using Assumption \ref{assum:sequences-ms-convergence}(e), we have $\mu_k^2\g_k\leq \rho \g_k^2\mu_k^{2\alpha}$. Thus, we obtain
\begin{align}\label{ineq:cond-recursive-F-k-expected2}
\EXP{f_{k+1}(x_{k+1})-f^*} &\leq (1-\lambda_{\min}\mu_k\g_k)\EXP{f_k(x_k)-f^*}\notag\\ &+\left(\frac{\rho\lambda_{\min}\mbox{dist}^2(x_0,X^*)+ (L+\mu_0)\lambda^2\nu^2}{2}\right)\mu^{2\alpha}_k\g_k^2.
\end{align}
Let us define \fy{$K\triangleq\max\{\hat K, K_0\}$, where $K_0$ is from Assumption \ref{assum:sequences-ms-convergence}(d)}. Using the preceding relation and by induction on $k$, we show the desired result. To show \eqref{ineq:bound}, we show the following relation first: 
\begin{align}\label{ineq:bound_v2}
 \EXP{f_{k+1}(x_{k+1})}-f^*\leq \theta\g_k\mu_k^{2\alpha-1}, \quad \hbox{for all } k \geq K,
 \end{align}
 Note that \eqref{ineq:bound_v2} \fy{implies} the relation \eqref{ineq:bound} since we have $ \EXP{f(x_{k+1})}\leq  \EXP{f_{k+1}(x_{k+1})}$.
First, we show that \eqref{ineq:bound_v2} holds for \fy{$k=K$}.  Consider the term $\EXP{f_{K+1}(x_{K+1})}-f^*$. Multiplying and dividing by $\g_K\mu_K^{2\alpha-1}$, we obtain
\begin{align*}\EXP{f_{K+1}(x_{K+1})}-f^*=\left(\frac{\EXP{f_{K+1}(x_{K+1})}-f^*}{\g_k\mu_K^{2\alpha-1}}\right)\g_K\mu_K^{2\alpha-1}
 \leq \theta \g_K\mu_K^{2\alpha-1},\end{align*}
where the last inequality is obtained by invoking the definition of $\theta$ in \eqref{def:theta}. This implies that \eqref{ineq:bound_v2} holds for $k=K$. Now assume that  \eqref{ineq:bound_v2} holds for some $k \geq K$. We show that it also holds for $k+1$.  From the induction hypothesis and \eqref{ineq:cond-recursive-F-k-expected2} we have
\begin{align*}
\EXP{f_{k+1}(x_{k+1})-f^*} &\leq (1-\lambda_{\min}\mu_k\g_k)\theta\g_{k-1}\mu_{k-1}^{2\alpha-1}\\ &+\left(\frac{\rho\lambda_{\min}\mbox{dist}^2(x_0,X^*)+ (L+\mu_0)\lambda^2\nu^2}{2}\right)\mu^{2\alpha}_k\g_k^2.
\end{align*}
Using Assumption \ref{assum:sequences-ms-convergence}(d) we obtain
\begin{align}\label{ineq:thm2-rel1}
\EXP{f_{k+1}(x_{k+1})-f^*} &\leq \theta\g_{k}\mu_{k}^{2\alpha-1}(1-\lambda_{\min}\mu_k\g_k)(1+\beta \lambda_{\min}\g_{k}\mu_{k})\notag \\ &+\left(\frac{\rho\lambda_{\min}\mbox{dist}^2(x_0,X^*)+ (L+\mu_0)\lambda^2\nu^2}{2}\right)\mu^{2\alpha}_k\g_k^2.
\end{align}
Next we find an upper bound for the term $(1-\lambda_{\min}\mu_k\g_k)(1+\beta \lambda_{\min}\g_{k}\mu_{k}) $ as follows
\begin{align*}
(1-\lambda_{\min}\mu_k\g_k)(1+\beta \lambda_{\min}\g_{k}\mu_{k}) &= 1-\lambda_{\min}\mu_k\g_k+\beta\lambda_{\min}\mu_k\g_k-\fy{\beta\lambda_{\min}^2\mu_k^2\g_k^2}\\ & \leq 1-(1-\beta)\lambda_{\min}\mu_k\g_k.
\end{align*}
Combining this relation with \eqref{ineq:thm2-rel1}, it follows \fy{that}
\begin{align*}%\label{ineq:thm2-rel1}
&\EXP{f_{k+1}(x_{k+1})-f^*} \leq \theta\g_{k}\mu_{k}^{2\alpha-1} -\theta\fy{\lambda_{\min}}(1-\beta)\mu_k^{2\alpha}\g_k^2  \\ &+\left(\frac{\rho\lambda_{\min}\mbox{dist}^2(x_0,X^*)+ (L+\mu_0)\lambda^2\nu^2}{2}\right)\mu^{2\alpha}_k\g_k^2\\ & =\theta\g_{k}\mu_{k}^{2\alpha-1}-\left(\underbrace{\theta\fy{\lambda_{min}}(1-\beta)-\frac{\rho\lambda_{\min}\mbox{dist}^2(x_0,X^*)+ (L+\mu_0)\lambda^2\nu^2}{2}}_{\tiny{\hbox{Term }1}}\right)\mu^{2\alpha}_k\g_k^2.
\end{align*}
Note that the definition of $\theta$ in \eqref{def:theta} implies that Term 1 is nonnegative. Therefore, 
\begin{align*}%\label{ineq:thm2-rel1}
\EXP{f_{k+1}(x_{k+1})-f^*} &\leq \theta\g_{k}\mu_{k}^{2\alpha-1}.
\end{align*}
Hence, the induction statement holds for $k+1$. We conclude that \eqref{ineq:bound_v2} holds for all $k\geq K$. As a consequence, \eqref{ineq:bound} holds for all $k\geq K$ as well. To complete the proof, we need to show $\lim_{k\to \infty}\EXP{f(x_{k})}=f^*$. This is an immediate result of \eqref{ineq:bound} and Assumption \ref{assum:sequences-ms-convergence}(a).
\end{proof}

\begin{lemma}\label{sumProductBounds}
Let $0 < a_1 \leq a_2 \leq \ldots \leq a_n$, and $P$ and $S$ be positive scalars such that \fys{$\sum_{i=1}^n a_i \leq S$ and $\prod_{i=1}^na_i \geq P$. Then, we have 
$a_1 \geq (n-1)!P/S^{n-1}$.}
\end{lemma}

\begin{proof}
See Appendix \ref{app:sumProductBounds}.
\end{proof}

\begin{lemma}[Properties of  update rule \eqref{eqn:H-k}-\eqref{eqn:H-k-m}]\label{LBFGS-matrix}
Consider the \eqref{eqn:LM-cyclic-reg-BFGS} method. Let $H_k$ be given by the update rule \eqref{eqn:H-k}-\eqref{eqn:H-k-m}, where $s_i$ and $y_i$ are defined in \eqref{equ:siyi-LBFGS} and $\mu_k$ is updated according to the procedure \eqref{eqn:mu-k}. Let \fy{Assumption \ref{assum:convex2}(a,b)} hold. Then, the following results hold:
\begin{itemize}
\item [(a)]  For any odd \fy{$k \geq 2m-1$}, the \fy{curvature condition} holds, i.e., \fy{$s_{\lceil k/2\rceil}^T{y_{\lceil k/2\rceil}} >0$}.
\item [(b)]  For any odd \fy{$k \geq 2m-1$}, the secant equation holds, i.e., \fy{$H_{k}{y}_{\lceil k/2\rceil}=s_{\lceil k/2\rceil}$}. 
\item [(c)] For any \fy{$k \geq 2m-1$}, $H_k$ satisfies Assumption \ref{assump:Hk} \fy{with} the following values:
\begin{align}\label{equ:valuesForAssumH_k}&\lambda_{\min}=\frac{1}{(m+n)\left(L+\fys{\tau}\mu_0^\delta\right)}, \quad \fy{\lambda= \frac{(m+n)^{n+m-1}\left(L+\fys{\tau}\mu_0^\delta\right)^{n+m-1}}{(n-1)!\fys{\tau^{(n+m)}}}}, \notag\\ & \fy{\hbox{and }\alpha=-\delta(n+m).}
\end{align}
More precisely, $H_k$ is symmetric, $\EXP{H_k\mid\sF_k}=H_k$ and
\begin{align}\label{proof:H_kbounds} \frac{1}{(m+n)\left(L+\fys{\tau}\mu_0^\delta\right)}\mathbf{I} \preceq H_{k} \preceq \frac{(m+n)^{n+m-1}\left(L+\fys{\tau}\mu_0^\delta\right)^{n+m-1}}{(n-1)!\fys{\left(\tau\mu_k^\delta\right)^{(n+m)}}}\ \mathbf{I}.
\end{align}
