Next, we derive a formula for $q_t$. From lines $\#$20-21 in the algorithm, we have
\begin{align*}
q_{K-t+1}&=q_{K-t} -\alpha_{K-t+1}y_t =q_{K-t} - \rho_t\left(s_t^Tq_{K-t}\right)y_t = q_{K-t} - \rho_t\left(y_ts_t^T\right)q_{K-t} \\
&= \left( \mathbf{I}-\rho_{t}y_ts_t^T\right)q_{K-t}=V_tq_{K-t}, \quad \hbox{for all } t= K, K-1, \ldots, K-m+1.
\end{align*}
From the preceding relation, we obtain
\begin{align}\label{equ:q_ell}
q_{\ell}=\left(\prod_{j=m-\ell+1}^{m}V_{K-(m-j)}\right)q_0, \quad \hbox{for all } \ell= 1,2, \ldots, m.
\end{align}
From the update rule for $\alpha_{i-t+1}$ in line $\#$20, using the definition of $\rho_t$, and applying the previous relation, we have $\alpha_1=\rho_{K}s_K^Tq_0$ and 
\begin{align}\label{equ:alpha_ell}
\alpha_{\ell}=\rho_{K-\ell+1}s_{K-\ell+1}^T\left(\prod_{j=m-\ell+2}^{m}V_{K-(m-j)}\right)q_0, \quad \hbox{for all } \ell= 2,3, \ldots, m.
\end{align}
\fys{Multiplying both sides of} \eqref{equ:H_kClosedForm} by $q_0$ and employing \eqref{equ:q_ell} and \eqref{equ:alpha_ell}, we obtain
\begin{align}\label{equ:H_kq_0}
H_{k,m}q_0 &=\left(\prod_{j=1}^{m}V_{K-(m-j)}\right)^TH_{k,0}q_m + \left(\prod_{j=2}^{m}V_{K-(m-j)}\right)^Ts_{K-m+1}\alpha_m \\
& + \left(\prod_{j=3}^{m}V_{K-(m-j)}\right)^Ts_{K-m+2}\alpha_{m-1}  +\ldots+V^T_{K}s_{K-1}\alpha_2+s_{K}\alpha_1.\notag
\end{align}
Next, we derive a formula for $r_t$. From line $\#$25 in the algorithm, we have 
\begin{align*}
r_{t-K+m}&=r_{t-K+m-1}+\left(\alpha_{K-t+1}-\rho_ty_t^Tr_{t-K+m-1}\right)s_t \\
&= r_{t-K+m-1}-\rho_ts_t y_t^Tr_{t-K+m-1}+\alpha_{K-t+1}s_t\\
& = V_t^Tr_{t-K+m-1}+\alpha_{K-t+1}s_t, \quad \hbox{for all } t= K-m+1,\ldots,K-1,  K.
\end{align*}
Combining the preceding two relations, we obtain
\begin{align*}
r_{\ell}&= V_{K-(m-\ell)}^Tr_{\ell-1}+\alpha_{m-\ell+1}s_{K-(m-\ell)}, \quad \hbox{for all } \ell= 1,2,\ldots,m.
