& + \alpha_{m-1} \left(\prod_{j=3}^{m}V_{K-(m-j)}\right)^Ts_{K-m+2} +\ldots+\alpha_2V^T_{K}s_{K-1}+\alpha_1s_{K}.\notag
\end{align}
From \eqref{equ:r_m} and \eqref{equ:H_kq_0}, and the definition of  $r_0$, we obtain $r_m=H_{k,m}q_0$. Taking to account the definition of $q_0$, the desired result holds for any odd $k\geq 2m-1$. Now, consider the case where $k\geq 2m-1$ is an even number. This implies that the ``if'' condition in line $\#$6 is skipped and as such, the value of $i$ is not updated from the iteration $k-1$, i.e.,  $i= \lceil (k-1)/2 \rceil$. Consequently, the LBFGS two-loop recursion at an even $k$ uses the following pairs 
$$\left\{(s_\ell,y_\ell)\mid \ell=\lceil (k-1)/2\rceil-m+1, \lceil (k-1)/2\rceil-m+2,\ldots,\lceil (k-1)/2\rceil\right\}.$$
\fys{Now,} considering the definition \eqref{eqn:H-k-m} for $k-1$, the desired relation can be shown following the same steps discussed for the case the iteration number is odd.}
%This implies the desired rate statement holds. 
\end{proof}

