%\an{The function $f(x)$ is convex on $\mathbb{R}^n$.} 
\item[(b)] For any $\xi \in \Omega$, $F(\cdot,\xi)$ is continuously differentiable \us{with Lipschitz
	continuous gradients} over $\Real^n$ with parameter $L_\xi>0$. Moreover, $L:=\sup_{\xi \in \Omega}L_\xi < \infty$. %Also, $\lim_{x\to \infty}f(x)< \infty$.
	\item[(c)] \ The optimal solution set $X^*$ of problem \eqref{eqn:problem} is nonempty. 
\end{enumerate}
\end{assumption}

\begin{algorithm}
  \caption{Iteratively Regularized Stochastic Limited-memory BFGS}
\label{algorithm:IR-S-BFGS}
%\begin{boxedminipage}{165mm}
    \begin{algorithmic}[1]
    \State\textbf{Input:} LBFGS memory parameter $m\geq 1$, Lipschitzian parameter $L>0$, random initial point $x_0 \in \Real^n$, initial stepsize $\g_0>0$, and initial regularization parameter $\mu_0>0$ such that $\g_0\mu_0 \leq  (m+n) L$, \fys{scalars $0<\epsilon < \frac{1}{3}$, $\delta \in \left(0,\frac{1.5\epsilon}{n+m}\right)$, and $\tau>0$}; 
    \State Set $a:=\frac{2}{3}-\epsilon+\frac{2\delta(n+m)}{3}$, $b:=\frac{1}{3}$;
    \For {$k=0,1,\ldots,$}
    		\State Compute $\g_k :=\frac{\g_0}{(k+1)^a}$ and $\mu_k:=\frac{\mu_02^b}{\left(k+1+\text{mod}(k+1,2)\right)^b}$;
        \State  {Evaluate the stochastic gradient $\nabla F(x_k,\xi_k)$;}
     \If {mod$(k,2)=1$}
    \State  Compute index $i:=\lceil k/2\rceil$;
     \State   Compute vector $s_i:=x_k-x_{k-1}$; 
     \State   Compute vector  $y_i:= \nabla F(x_k,\xi_{k-1})-\nabla F(x_{k-1},\xi_{k-1})+\fys{\tau}\mu_k^\delta s_i$;
      \If {$k> 2m$}
      \State Discard the vector pair $\{s_{i-m},y_{i-m}\}$ from storage;
      \EndIf
   \EndIf
 \If {$k < 2m-1$}
   \State Update solution iterate $x_{k+1}:=x_k-\g_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right)$;
     \Else
     \State Initialize Hessian inverse $H_{k,0}:=\frac{s_i^Ty_i}{y_i^Ty_i}\mathbf{I}$;\hspace{.4in} \tikzmark{right}\tikzmark{top}
     \State Initialize $q:=\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)$;
     \For {$t=i:i-m+1$}
     \State Compute scalar $\alpha_{i-t+1}:=\frac{s_t^Tq}{s_t^Ty_t}$;
     \State Update vector $q:=q-\alpha_{i-t+1}y_t$;
     \EndFor
     \State Initialize vector $r:=H_{k,0}q$;
     \For {$t=i-m+1:i$}
     %\State Compute scalar $\beta:=\frac{y_t^Tr}{s_t^Ty_t}$;
     \State  Update vector $r:=r+\left(\alpha_{i-t+1}-\frac{y_t^Tr}{s_t^Ty_t}\right)s_t$;
     \EndFor\tikzmark{bottom}
%\State Given $\mathcal{M}=\{(s_t,y_t)\}_{t=i-m+1}^i$, call Alg. \ref{algorithm:Hk-update} to compute the following vector\[G_k \triangleq H_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right);\]
             \State Update solution iterate $x_{k+1}:=x_k-\g_kr$;\Comment{\footnotesize{LBFGS update}} 

\EndIf

    \EndFor
   \end{algorithmic}
   \AddNote{top}{bottom}{right}{\footnotesize{LBFGS two-loop recursion}}
%\end{boxedminipage}
% \vskip17.5pt
\end{algorithm}

\begin{property}[{Properties of a regularized function}]\label{proper:propsfk} We have:
\begin{itemize}
\item [(a)] $f_k$ is strongly convex with a parameter $\mu_k$.
\item [(b)] $f_k$ has Lipschitzian gradients with parameter $L+\mu_k$.
 \item [(c)] $f_k$ has a unique minimizer over $\Real^n$, denoted by $x^*_k$. Moreover, for any $x \in \Real^n$, 
 \[2\mu_k (f_k(x)-f_k(x^*_k)) \leq \|\nabla f_k(x)\|^2\leq 2(L+\mu_k) (f_k(x)-f_k(x^*_k)).\]
\end{itemize}
\end{property}

\begin{lemma}[A recursive error bound]\label{lemma:main-ineq}
Consider the \eqref{eqn:LM-cyclic-reg-BFGS} method and suppose Assumptions \ref{assum:convex}, \ref{assum:main}, and \ref{assump:Hk} hold. Also, assume $\mu_k$ is a non-increasing sequence and let \begin{align}\label{mainLemmaCond}\g_k\mu_k^{2\alpha} \leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_0)},\quad \hbox{for all }k\geq 0.
\end{align}Then, the following inequality holds \fy{for all $k\geq 0$}:
\begin{align}\label{ineq:cond-recursive-F-k}
\EXP{f_{k+1}(x_{k+1})\mid\sF_k}-f^* &\leq (1-\lambda_{\min}\mu_k\g_k)(f_k(x_k)-f^*)+\frac{\lambda_{\min}\mbox{dist}^2(x_0,X^*)}{2}\mu_k^2\g_k\notag \\ &+\frac{ (L+\mu_k)\lambda^2\nu^2}{2}\mu^{2\alpha}_k\g_k^2.
\end{align}
\end{lemma}

\begin{proof}
The Lipschitzian property of $\nabla f_k$ and  
the update rule \eqref{eqn:LM-cyclic-reg-BFGS} imply that 
\begin{align*}
f_k(x_{k+1}) &\leq f_k(x_k)+\nabla f_k(x_k)^T(x_{k+1}-x_k)+\frac{ (L+\mu_k)}{2}\|x_{k+1}-x_k\|^2 \cr
&= f_k(x_k)-\g_k\nabla f_k(x_k)^TH_k\left(\nabla F(x_k,\xi_k) +\mu_k(x_k-x_0)\right)\\&+ \frac{ (L+\mu_k)}{2}\g_k^2\|H_k\left(\nabla F(x_k,\xi_k)+\mu_k(x_k-x_0)\right)\|^2.\end{align*}
\fy{Invoking the definition of the stochastic error $w_k$ in} \eqref{def:wk} \fy{and} Definition~\ref{def:regularizedF}, we obtain
\begin{align}\label{ineq:term1-2}
f_k(x_{k+1}) &\leq f_k(x_k)-\g_k\nabla f_k(x_k)^TH_k(\nabla f(x_k)+w_k +\mu_k(x_k-x_0))\notag\\&+ \frac{ (L+\mu_k)}{2}\g_k^2\|H_k(\nabla f(x_k)+w_k+\mu_k(x_k-x_0))\|^2\\ 
\notag = f_k(x_k)&-\g_k\underbrace{\nabla f_k(x_k)^TH_k(\nabla f_k(x_k)+w_k)}_{\tiny\hbox{Term } 1}+ \frac{ (L+\mu_k)}{2}\g_k^2\underbrace{\|H_k(\nabla f_k(x_k)+w_k)\|^2}_{\tiny\hbox{ Term } 2},\end{align}
where in the last \fy{equation,} we used the definition of $f_k$. Next, we estimate the conditional expectation of Term 1 and 2. From Assumption \ref{assump:Hk}, we have 
\begin{align*}
\hbox{Term }1 &= \nabla f_k(x_k)^TH_k\nabla f_k(x_k)+\nabla f_k(x_k)^TH_kw_k \\&\geq \lambda_{\min}\|\nabla f_k(x_k)\|^2+\nabla f_k(x_k)^TH_kw_k.
\end{align*}
Taking expectations conditioned on $\sF_k$, from the preceding inequality, we obtain
\begin{align}\label{equ:Term1}
\EXP{\hbox{Term } 1\mid\sF_k} &\geq \lambda_{\min}\|\nabla f_k(x_k)\|^2+\EXP{\nabla f_k(x_k)^TH_kw_k\mid\sF_k}\\ \notag&=\lambda_{\min}\|\nabla f_k(x_k)\|^2+\nabla f_k(x_k)^TH_k\EXP{w_k\mid\sF_k} =\lambda_{\min}\|\nabla f_k(x_k)\|^2,\end{align}
where we recall that $\EXP{w_k\mid\sF_k}=0$ and $\EXP{H_k\mid\sF_k}=H_k$. Similarly, in Term 2, invoking Assumption \ref{assump:Hk}(b), we may write
\begin{align*}
\hbox{Term } 2&= (\nabla f_k(x_k)+w_k)^TH_k^2(\nabla f_k(x_k)+w_k)\leq (\lambda\mu^{\alpha}_k)^2\|\nabla f_k(x_k)+w_k\|^2 \\ &=\lambda^2\mu^{2\alpha}_k\left(\|\nabla f_k(x_k)\|^2+\|w_k\|^2+2\nabla f_k(x_k)^Tw_k\right).\end{align*}
Taking conditional expectations from the preceding inequality, and using Assumption \ref{assum:main}, we obtain
\begin{align}\label{equ:Term2}
\EXP{\hbox{Term } 2\mid\sF_k}&\leq\lambda^2\mu^{2\alpha}_k\left(\|\nabla f_k(x_k)\|^2+\EXP{\|w_k\|^2\mid\sF_k}+2\nabla f_k(x_k)^T\EXP{w_k\mid\sF_k}\right)\notag\\ & \leq \lambda^2\mu^{2\alpha}_k\left(\|\nabla f_k(x_k)\|^2+\nu^2\right).\end{align}
Next, taking conditional expectations in \eqref{ineq:term1-2}, and using \eqref{equ:Term1} and \eqref{equ:Term2}, we obtain
\begin{align*}%\label{ineq:lemma2rel7}
&\EXP{f_k(x_{k+1})\mid\sF_k} \leq f_k(x_k)-\g_k\lambda_{\min}\|\nabla f_k(x_k)\|^2\notag \\
&+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\left(\|\nabla f_k(x_k)\|^2+\nu^2\right)\notag \\
&\leq f_k(x_k)-\frac{\g_k\lambda_{\min}}{2}\|\nabla f_k(x_k)\|^2\left(2-\frac{\lambda^2\mu_k^{2\alpha}\g_k(L+\mu_k)}{\lambda_{\min}}\right)+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align*}
From the assumption that $\g_k$ and $\mu_k$ satisfy $\g_k\mu^{2\alpha}_k \leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_0)}$ for any $k \geq 0$ and that $\mu_k$ is non-increasing, we have $\g_k\mu^{2\alpha}_k \leq \frac{\lambda_{\min}}{\lambda^2(L+\mu_k)}$. As a consequence, we get $2-\frac{\lambda^2\mu_k^{2\alpha}\g_k(L+\mu_k)}{\lambda_{\min}}\geq 1$.  Therefore, from \fy{the} preceding inequality, we obtain
\begin{align*}
\EXP{f_k(x_{k+1}) \mid\sF_k}&\leq f_k(x_k)-\frac{\g_k\lambda_{\min}}{2}\|\nabla f_k(x_k)\|^2+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align*}
Employing Property \ref{proper:propsfk}(c), we have
\begin{align*}
\EXP{f_k(x_{k+1})\mid\sF_k} &\leq f_k(x_k)-\lambda_{\min}\mu_k\g_k(f_k(x_k)-f_k(x^*_k))+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align*}
Note that, since $\mu_k$ is a non-increasing sequence, Definition \ref{def:regularizedF} implies that \[\EXP{f_{k+1}(x_{k+1})\mid \sF_k} \leq\EXP{f_{k}(x_{k+1})\mid \sF_k}.\] Therefore, we obtain 
\begin{align}\label{ineq:lemmaLastIneq}
\EXP{f_{k+1}(x_{k+1})\mid\sF_k} &\leq f_k(x_k)-\lambda_{\min}\mu_k\g_k(\underbrace{f_k(x_k)-f_k(x^*_k)}_{\tiny{\hbox{Term } 3}})+\lambda^2\mu^{2\alpha}_k\frac{ (L+\mu_k)}{2}\g_k^2\nu^2.
\end{align}
Next, we derive a lower bound for Term 3. Since $x_k^*$ is the unique minimizer of $f_k$, we have $f_k(x_k^*) \leq f_k(x^*)$. Therefore, invoking Definition \ref{def:regularizedF}, for an arbitrary optimal solution $x^* \in X^*$, we have 
\[f_k(x_k)-f_k(x^*_k)\geq f_k(x_k)-f_k(x^*)=f_k(x_k)-f^*-\frac{\mu_k}{2}\|x^*-x_0\|^2.\]
From the preceding relation and \eqref{ineq:lemmaLastIneq}, we have
\begin{align*}
\EXP{f_{k+1}(x_{k+1})\mid\sF_k} &\leq f_k(x_k)-\lambda_{\min}\mu_k\g_k(f_k(x_k)-f^*)+\frac{\lambda_{\min}\|x^*-x_0\|^2}{2}\mu_k^2\g_k\\
&+\frac{(L+\mu_k)\lambda^2\nu^2}{2}\mu^{2\alpha}_k\g_k^2.
\end{align*}
Since $x^*$ is an arbitrary optimal solution, taking minimum from the right-hand side of the preceding inequality over $X^*$, we can replace $\|x^*-x_0\|$ by $\mbox{dist}(x_0,X^*)$. Then, subtracting $f^*$ from both sides of the resulting relation yields the desired inequality.
\end{proof}

